    ws_out = wb_out[sname]
    for row in ws_orig.iter_rows(min_row=1, max_row=ws_orig.max_row, max_col=ws_orig.max_column):
        for cell_orig in row:
            cell_out = ws_out.cell(row=cell_orig.row, column=cell_orig.column)
            if font_key(cell_orig.font) != font_key(cell_out.font):
                diffs += 1
                if diffs <= 5:
                    print(f"FONT DIFF: {sname}!{cell_orig.coordinate}")
            if fill_key(cell_orig.fill) != fill_key(cell_out.fill):
                diffs += 1
                if diffs <= 5:
                    print(f"FILL DIFF: {sname}!{cell_orig.coordinate}")
            if cell_orig.number_format != cell_out.number_format:
                diffs += 1
                if diffs <= 5:
                    print(f"NUMFMT DIFF: {sname}!{cell_orig.coordinate}: {cell_orig.number_format} vs {cell_out.number_format}")
            if border_key(cell_orig.border) != border_key(cell_out.border):
                diffs += 1
                if diffs <= 5:
                    print(f"BORDER DIFF: {sname}!{cell_orig.coordinate}")

print(f"Total formatting diffs: {diffs}")
